using System;

namespace Silvtek.ORMEngine
{
	/// <summary>
	/// Data Object Exception.
	/// </summary>
	[Serializable]
	public class ORMException : ApplicationException
	{
	    private string sql;

        /// <summary>
        /// Gets the last SQL generated by the ORM engine. 
        /// </summary>
        /// <value>The last SQL.</value>
	    public string LastSql
	    {
            get { return sql; }
	    }

        /// <summary>
        /// Initializes a new instance of the <see cref="ORMException"/> class.
        /// </summary>
        /// <param name="sql">The SQL.</param>
        /// <param name="msg">The MSG.</param>
        public ORMException(string sql, string msg) : base(msg)
        {
            this.sql = sql;
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="ORMException"/> class.
        /// </summary>
        /// <param name="msg">The MSG.</param>
		public ORMException(string msg) : base (msg)
		{
		    sql = String.Empty;

		}

        /// <summary>
        /// Initializes a new instance of the <see cref="ORMException"/> class.
        /// </summary>
        /// <param name="msg">The MSG.</param>
        /// <param name="innerExp">The inner exp.</param>
		public ORMException(string msg, Exception innerExp) : base(msg, innerExp)
		{
		    sql = String.Empty;

		}

        public ORMException(string msg, string sql, Exception innerExp)
            : base(msg, innerExp)
        {
            this.sql = sql;

        }
	}
}
